{
    "export": "23/08/2022",
    "framework": [
        "boxe",
        "defense"
    ],
    "list": [
        {
            "name": "guarda e bloqueio",
            "check": true,
            "description": "Seus punhos e antebraços são sua melhor defesa contra qualquer golpe de seu oponente. Basta erguer as mãos até encobrirem o rosto. Alguns lutadores usam o bloqueio parcial, onde uma das mãos fica mais aberta e pronta para realizar um contra-ataque rápido e eficiente."
        },
        {
            "name": "esquiva",
            "check": true,
            "description": "Seja rápido na sua defesa. Principalmente ao se esquivar. Um passo atrás e os golpes rápidos pegam apenas o vento, uma girada basta para o golpe passar a raspar a sua cabeça, porém, é o momento favorecedor para um contra-ataque."
        },
        {
            "name": "clinch",
            "check": true,
            "description": "Aproxime-se do adversário, perto o bastante para abraçá-lo e tirar a força de seus golpes ao te atingirem e reduzir a velocidade dele. Nessa tática o juiz tende a intervir para separar os lutadores."
        }
    ]
}

{
    "export": "23/08/2022",
    "framework": [
        "boxe",
        "blow"
    ],
    "list": [
        {
            "name": "jab",
            "check": true,
            "description": "É um golpe reto e frontal, dado com a mão da frente da guarda de boxe (vê imagem abaixo), com a intenção de afastar e manter uma certa um distância, considerada segura, do adversário. Não é um golpe realizado com muita potência, porém, caso o adversário já esteja debilito, um Jab certeiro pode levar a um nocaute."
        },
        {
            "name": "direto",
            "check": true,
            "description": "É um soco reto dado com a mão de trás da guarda de boxe (vê imagem abaixo) e aplicado frontalmente no adversário com muita potência. Você o aplica com força com intenção de derrubar (nocautear) o oponente."
        },
        {
            "name": "gancho",
            "check": true,
            "description": "É um golpe feito de baixo para cima na diagonal, que geralmente funciona por ser curto, rápido e potente, podendo quebrar a defesa do oponente pelos lados."
        },
        {
            "name": "uppercut",
            "check": true,
            "description": "Este golpe é realizado sentido baixo para cima na vertical, afim de acertar o queixo do rival, mas, pode também pode ser aplicado como uma quebra de barreira."
        },
        {
            "name": "cruzado",
            "check": true,
            "description": "É como o golpe lateral com movimento horizontal, com o objetivo de atingir a lateral da cabeça com intensidade de força. Para realizá-lo, flexione o braço de modo a acertar a lateral do rosto do adversário."
        },
        {
            "name": "swing",
            "check": true,
            "description": "É um golpe cruzado feito em diagonal e de cima para baixo com a intenção de acertar a cabeça do oponente. É preciso dar uma passada lateral com a perna da frente e soltar o golpe gol a mão de trás."
        },
        {
            "name": "overhand",
            "check": true,
            "description": "É um golpe cruzado feito em diagonal e de cima para baixo com a intenção de acertar a cabeça do oponente. É preciso dar uma passada lateral com a perna da frente e soltar o golpe gol a mão de trás."
        }
    ]
}

